def smallest_subsequence(S, K):
    stack = []
    n = len(S)

    for i in range(n):
        while stack and stack[-1] > S[i] and len(stack) - 1 + (n - i) >= K:
            stack.pop()
        if len(stack) < K:
            stack.append(S[i])

    return ''.join(stack)

def main():
    T = int(input())
    for _ in range(T):
        S = input()
        K = int(input())
        print(smallest_subsequence(S, K))

